function Boton({ valor, onIncrementar }) {
  return (
    <button onClick={onIncrementar}>
      +1 (valor actual: {valor})
    </button>
  );
}

function App() {
  const [a, setA] = useState(0);
  const [b, setB] = useState(0);

  return (
    <div>
      <Boton valor={a} onIncrementar={() => setA(prev => prev + 1)} />
      <Boton valor={b} onIncrementar={() => setB(prev => prev + 1)} />
      <p>Total: {a + b}</p>
    </div>
  );
}

root.render(<App />);
